package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws Exception
  {
    final ObjectMapper mapper = new DefaultObjectMapper();
    mapper.setInjectableValues(
        new InjectableValues.Std().addValue(
            JavaScriptConfig.class,
            new JavaScriptConfig(false) // Disabled
        )
    );

    // Legitimate JSON
    String json = "{\"type\":\"javascript\",\"dimension\":\"dim\",\"function\":\"function(x) { return true; }\"}";
    JavaScriptDimFilter filter = (JavaScriptDimFilter) mapper.readValue(json, DimFilter.class);

    try {
      filter.toFilter();
      Assert.fail("Should have thrown exception because JavaScript is disabled");
    }
    catch (IllegalStateException e) {
      Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }

    // Exploit JSON with empty key bypass
    String exploitJson = "{"
                         + "\"type\":\"javascript\","
                         + "\"dimension\":\"dim\","
                         + "\"function\":\"function(x) { return true; }\","
                         + "\"\":{\"enabled\":true}"
                         + "}";

    JavaScriptDimFilter exploitFilter = (JavaScriptDimFilter) mapper.readValue(exploitJson, DimFilter.class);

    // If vulnerable, this will NOT throw an exception
    try {
      exploitFilter.toFilter();
      Assert.fail("Should have thrown exception even with exploit JSON because JavaScript is disabled and bypass should not work");
    }
    catch (IllegalStateException e) {
      Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }
  }
}

